using System.Diagnostics;
using System.Globalization;
using System.Runtime.CompilerServices;
using BadgeSmith.Api.Core;
using BadgeSmith.Api.Core.Http;
using Microsoft.Extensions.Caching.Memory;

if (args is ["version-contract", var expectedVersion])
{
    var first = Settings.ApplicationVersion;
    if (!string.Equals(first, expectedVersion, StringComparison.Ordinal))
    {
        throw new InvalidOperationException("Application version does not match the supplied contract expectation.");
    }

    Environment.SetEnvironmentVariable("APP_VERSION", "changed-after-first-read");
    if (!string.Equals(Settings.ApplicationVersion, first, StringComparison.Ordinal))
    {
        throw new InvalidOperationException("Application version was not cached after its first read.");
    }

    Console.WriteLine(string.Create(CultureInfo.InvariantCulture, $"version-contract={true}"));
    return;
}

if (args.Length != 1)
{
    throw new ArgumentException("Specify a probe sequence.", nameof(args));
}

var sequence = args[0] switch
{
    "cache" => new[] { "cache" },
    "registry-cache" => ["registry", "registry-cache"],
    "nuget-github" => ["nuget", "github", "github"],
    "http-before" => ["before-nuget", "before-github", "before-github"],
    "http-after" => ["after-nuget", "after-github", "after-github"],
    _ => throw new ArgumentException("Unknown probe sequence.", nameof(args))
};

foreach (var step in sequence)
{
    var before = GC.GetAllocatedBytesForCurrentThread();
    var started = Stopwatch.GetTimestamp();
    var instance = Create(step);
    using var owned = instance as IDisposable;
    var elapsed = Stopwatch.GetElapsedTime(started);
    var allocated = GC.GetAllocatedBytesForCurrentThread() - before;
    GC.KeepAlive(instance);
    Console.WriteLine(string.Create(CultureInfo.InvariantCulture, $"{step}\t{allocated}\t{elapsed.TotalMicroseconds:F3}"));
}

[MethodImpl(MethodImplOptions.NoInlining)]
static object Create(string step) => step switch
{
    "cache" => new MemoryCache(new MemoryCacheOptions()),
    "registry" => ApplicationRegistry.ApiRouter,
    "registry-cache" => ApplicationRegistry.MemoryAppCache,
    "nuget" => HttpClientFactory.CreateNuGetClient(),
    "github" => HttpClientFactory.CreateGithubClient(),
    "before-nuget" => BaselineHttpClientFactory.CreateNuGetClient(),
    "before-github" => BaselineHttpClientFactory.CreateGithubClient(),
    "after-nuget" => CandidateHttpClientFactory.CreateNuGetClient(),
    "after-github" => CandidateHttpClientFactory.CreateGithubClient(),
    _ => throw new ArgumentException("Unknown probe step.", nameof(step))
};

